#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricPotential::new(v, ElectricPotentialUnit::Volt),
        ElectricPotential::from_volts(v)
    );
    assert_eq!(
        ElectricPotential::from_base(v).convert_to(ElectricPotentialUnit::Volt),
        ElectricPotential::from_base(v).as_volts()
    );
    assert_eq!(
        ElectricPotential::new(v, ElectricPotentialUnit::Nanovolt),
        ElectricPotential::from_nanovolts(v)
    );
    assert_eq!(
        ElectricPotential::from_base(v).convert_to(ElectricPotentialUnit::Nanovolt),
        ElectricPotential::from_base(v).as_nanovolts()
    );
    assert_eq!(
        ElectricPotential::new(v, ElectricPotentialUnit::Microvolt),
        ElectricPotential::from_microvolts(v)
    );
    assert_eq!(
        ElectricPotential::from_base(v).convert_to(ElectricPotentialUnit::Microvolt),
        ElectricPotential::from_base(v).as_microvolts()
    );
    assert_eq!(
        ElectricPotential::new(v, ElectricPotentialUnit::Millivolt),
        ElectricPotential::from_millivolts(v)
    );
    assert_eq!(
        ElectricPotential::from_base(v).convert_to(ElectricPotentialUnit::Millivolt),
        ElectricPotential::from_base(v).as_millivolts()
    );
    assert_eq!(
        ElectricPotential::new(v, ElectricPotentialUnit::Kilovolt),
        ElectricPotential::from_kilovolts(v)
    );
    assert_eq!(
        ElectricPotential::from_base(v).convert_to(ElectricPotentialUnit::Kilovolt),
        ElectricPotential::from_base(v).as_kilovolts()
    );
    assert_eq!(
        ElectricPotential::new(v, ElectricPotentialUnit::Megavolt),
        ElectricPotential::from_megavolts(v)
    );
    assert_eq!(
        ElectricPotential::from_base(v).convert_to(ElectricPotentialUnit::Megavolt),
        ElectricPotential::from_base(v).as_megavolts()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricPotential::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricPotential::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricPotentialUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricPotential::from_base(0.0).auto_unit().unit,
        ElectricPotentialUnit::Volt
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "V".parse::<ElectricPotentialUnit>(),
        Ok(ElectricPotentialUnit::Volt)
    );
    assert_eq!(
        format!("2.5 {}", "V").parse::<ElectricPotential>(),
        Ok(ElectricPotential::new(2.5, ElectricPotentialUnit::Volt))
    );
    assert_eq!(
        "nV".parse::<ElectricPotentialUnit>(),
        Ok(ElectricPotentialUnit::Nanovolt)
    );
    assert_eq!(
        format!("2.5 {}", "nV").parse::<ElectricPotential>(),
        Ok(ElectricPotential::new(2.5, ElectricPotentialUnit::Nanovolt))
    );
    assert_eq!(
        "µV".parse::<ElectricPotentialUnit>(),
        Ok(ElectricPotentialUnit::Microvolt)
    );
    assert_eq!(
        format!("2.5 {}", "µV").parse::<ElectricPotential>(),
        Ok(ElectricPotential::new(
            2.5,
            ElectricPotentialUnit::Microvolt
        ))
    );
    assert_eq!(
        "mV".parse::<ElectricPotentialUnit>(),
        Ok(ElectricPotentialUnit::Millivolt)
    );
    assert_eq!(
        format!("2.5 {}", "mV").parse::<ElectricPotential>(),
        Ok(ElectricPotential::new(
            2.5,
            ElectricPotentialUnit::Millivolt
        ))
    );
    assert_eq!(
        "kV".parse::<ElectricPotentialUnit>(),
        Ok(ElectricPotentialUnit::Kilovolt)
    );
    assert_eq!(
        format!("2.5 {}", "kV").parse::<ElectricPotential>(),
        Ok(ElectricPotential::new(2.5, ElectricPotentialUnit::Kilovolt))
    );
    assert_eq!(
        "MV".parse::<ElectricPotentialUnit>(),
        Ok(ElectricPotentialUnit::Megavolt)
    );
    assert_eq!(
        format!("2.5 {}", "MV").parse::<ElectricPotential>(),
        Ok(ElectricPotential::new(2.5, ElectricPotentialUnit::Megavolt))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricPotential>(),
        Err(ParseError::UnknownUnit)
    );
}

